"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95000"],{83751(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_documento.codigo_formato_invalido","status":422,"titulo":"Formato do c\xf3digo do tipo de documento inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.tipo_documento.codigo_formato_invalido","requisitos":["UNI-REQ-0013"],"oQueAconteceu":["O **c\xf3digo** informado n\xe3o respeita o formato fechado \u2014\\n`^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$`: inicia com letra mai\xfascula, segue com letras\\nmai\xfasculas, d\xedgitos e sublinhado, com at\xe9 50 caracteres no total (ex.: `RG`,\\n`LAUDO_MEDICO`, `DECLARACAO_IRPF_2025`).","S\xe3o recusados, entre outros, o c\xf3digo em caixa baixa (`laudo_medico`), o que\\ncome\xe7a por d\xedgito (`01`), o que traz caractere acentuado (`LAUDO_M\xc9DICO`), o\\nque usa h\xedfen no lugar do sublinhado (`LAUDO-MEDICO`).","O d\xedgito \xe9 aceito em qualquer posi\xe7\xe3o **menos a primeira**. \xc9 essa restri\xe7\xe3o\\nque separa o c\xf3digo sem\xe2ntico da numera\xe7\xe3o sequencial: preserva usos leg\xedtimos\\ncomo `DECLARACAO_IRPF_2025`, onde o n\xfamero \xe9 o exerc\xedcio fiscal, e `LEI_12711`,\\nonde \xe9 o n\xfamero da lei \u2014 e recusa `01`, que n\xe3o identifica nada por si.","O c\xf3digo do tipo de documento n\xe3o \xe9 r\xf3tulo de exibi\xe7\xe3o. \xc9 a chave de igualdade\\ncom que o sistema decide se as exig\xeancias documentais de um edital satisfazem a\\nregra legal aplic\xe1vel, e \xe9 congelado no registro imut\xe1vel da publica\xe7\xe3o. Um\\nedital publicado guarda o c\xf3digo tal como estava no momento em que foi\\ncongelado, de modo que corrigir o cadastro depois n\xe3o corrige o edital j\xe1\\npublicado.","Da\xed a exig\xeancia de um c\xf3digo que se explique por leitura: `LAUDO_MEDICO`\\nidentifica o documento em qualquer contexto; `01` s\xf3 faz sentido para quem tem\\na tabela de correspond\xeancia \xe0 m\xe3o."],"comoResolver":["Informe um c\xf3digo que comece com letra mai\xfascula e contenha apenas letras\\nmai\xfasculas, d\xedgitos e sublinhado, com at\xe9 50 caracteres \u2014 e que nomeie o\\ndocumento, n\xe3o a sua posi\xe7\xe3o numa lista.","No cadastro pela interface, o c\xf3digo \xe9 sugerido a partir do nome e permanece\\nedit\xe1vel antes de salvar."],"ondeAparece":["Cria\xe7\xe3o de um tipo de documento","Atualiza\xe7\xe3o de um tipo de documento"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo documento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);